-- Rollback script generated by database-diff on <time>
-- Source (the sync script's model):  <server> / ddtest_edge_src
-- Target (will be changed back):     <server> / ddtest_edge_tgt
--
-- Running this on the TARGET database after the sync script of the same comparison puts its
-- schema back as it was read during the comparison. REVIEW IT BEFORE RUNNING.
-- - Nothing in this file has been executed by database-diff.
-- - It assumes the target changed only through the sync script since the comparison.
-- - Database triggers (ON DATABASE) come first: the ones the sync script created or changed are
--   disabled, dropped or put back, and only then enabled as they were before. An enabled one
--   fires on the statements after it and may refuse them.
-- - Procedures, views, functions, triggers, synonyms, indexes and constraints the sync script
--   created are dropped next, with IF EXISTS so a sync script that stopped part way is fine.
-- - Tables, columns, sequences, types and schemas it created are commented out at the end:
--   dropping them loses the data written since.
-- - Changed objects get their earlier definition back. ALTER COLUMN statements are active:
--   check them for data loss (narrower types, NOT NULL). Except the change of a column that a
--   computed column uses: SQL Server refuses it (Msg 5074), so it is written as a group of
--   comments to run by hand (those computed columns dropped, the change, the columns added
--   again).
-- - A view that is altered back gets the indexes it had created again right after it (ALTER
--   VIEW drops every index of a view). The indexes of the other views come after the views.
-- - Objects only in the target are not here: the sync script leaves them (its drops are
--   commented out). Schemas, types and sequences it created only when missing are left in place.
-- - Only a backup brings back dropped data.
-- - Objects are ordered by kind, not by dependency; rerun a failed part after the rest.
-- - Uses CREATE OR ALTER and DROP IF EXISTS: SQL Server 2016 SP1 or later on the target.
-- - It starts with USE of the target database. If that fails (wrong server, no access), nothing
--   after it is executed, so no statement runs in another database.
-- - A changed index, constraint or default is dropped and created again in one transaction (a
--   default also around the type change of its column), under the SET XACT_ABORT ON below
--   (keep it when running only a part of this file): when a statement in it fails, the drop
--   is rolled back and the existing one stays.
USE [ddtest_edge_tgt];
GO
IF DB_ID(N'ddtest_edge_tgt') IS NULL OR DB_ID() <> DB_ID(N'ddtest_edge_tgt')
BEGIN
    RAISERROR(N'database-diff: cannot use database %s. The rest of this file is not executed.', 16, 1, N'ddtest_edge_tgt');
    SET NOEXEC ON;
END
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
GO

-- ==========================================================================================
-- User-defined types
-- ==========================================================================================
-- Type dbo.IdList differs: Spec: source (Id int NOT NULL), target (Id bigint NOT NULL)
-- A type cannot be altered: drop the objects that use it, DROP TYPE, CREATE TYPE, then recreate them.
-- Type dbo.KeyList differs: Details: source Qty DEFAULT ((1)); PRIMARY KEY CLUSTERED (Id), target Qty DEFAULT ((2))
-- A type cannot be altered: drop the objects that use it, DROP TYPE, CREATE TYPE, then recreate them.

-- ==========================================================================================
-- Columns
-- ==========================================================================================
-- dbo.Items.Status: Default: source (N'รอดำเนินการ'), target (N'เสร็จแล้ว')
BEGIN TRANSACTION;
DECLARE @default sysname, @drop nvarchar(max);
SELECT @default = dc.name FROM sys.default_constraints dc JOIN sys.columns c ON c.object_id = dc.parent_object_id AND c.column_id = dc.parent_column_id WHERE dc.parent_object_id = OBJECT_ID(N'[dbo].[Items]') AND c.name = N'Status';
IF @default IS NOT NULL BEGIN SET @drop = N'ALTER TABLE [dbo].[Items] DROP CONSTRAINT ' + QUOTENAME(@default); EXEC (@drop); END
ALTER TABLE [dbo].[Items] ADD DEFAULT (N'เสร็จแล้ว') FOR [Status];
COMMIT TRANSACTION;
GO
-- dbo.Items.Total: Type: source decimal(21,2), target decimal(23,2) Computed: source ([Qty]*[Price]), target (([Qty]*[Price])*(1))
-- IDENTITY or computed definition differs: SQL Server cannot ALTER this; rebuild the column or table manually.
GO
-- dbo.Pnn.Twice: Nullable: source NOT NULL, target NULL
-- Not scripted: SQL Server cannot ALTER the type, collation or NULL / NOT NULL of a computed column; they follow from its definition and the columns it uses.
-- NOT NULL is part of how a persisted computed column is declared: to change it, drop the column and add it again (indexes and constraints that use it first):
-- ALTER TABLE [dbo].[Pnn] DROP COLUMN [Twice];
-- ALTER TABLE [dbo].[Pnn] ADD [Twice] AS ([Qty]*(2)) PERSISTED;
GO

-- ==========================================================================================
-- Indexes, primary keys and unique constraints
-- ==========================================================================================
-- dbo.Items (primary key): Name: source (system-named), target PK_Items
-- Primary key differs. Foreign keys that reference it must be dropped first, so this is left commented out:
-- ALTER TABLE [dbo].[Items] DROP CONSTRAINT [PK__Items__<id>];
-- ALTER TABLE [dbo].[Items] ADD CONSTRAINT [PK_Items] PRIMARY KEY CLUSTERED ([ID]);
GO
-- dbo.Items.IX_Items_Title: Filter: source ([Title] IS NOT NULL), target (none)
BEGIN TRANSACTION;
DROP INDEX [IX_Items_Title] ON [dbo].[Items];
CREATE NONCLUSTERED INDEX [IX_Items_Title] ON [dbo].[Items] ([Title]);
COMMIT TRANSACTION;
GO

-- ==========================================================================================
-- Check constraints
-- ==========================================================================================
-- dbo.Items.CK_Items_Code: State: source ENABLED, target DISABLED
ALTER TABLE [dbo].[Items] NOCHECK CONSTRAINT [CK_Items_Code];
GO

-- ==========================================================================================
-- Functions
-- ==========================================================================================
-- dbo.fKind: Definition differs Type: source SQL_INLINE_TABLE_VALUED_FUNCTION, target SQL_SCALAR_FUNCTION
-- The object type changed, which ALTER cannot do. To change it, drop the object and create it again by hand:
-- DROP FUNCTION [dbo].[fKind];
-- GO
-- CREATE FUNCTION dbo.fKind () RETURNS int AS BEGIN RETURN 1; END;
-- GO

-- ==========================================================================================
-- Stored procedures
-- ==========================================================================================
-- dbo.pCase: Definition differs
GO
CREATE OR ALTER PROCEDURE dbo.pCase AS select 1 as one;

GO
-- dbo.pSpaces: Definition differs
GO
CREATE OR ALTER PROCEDURE dbo.pSpaces AS SELECT 1 AS One;

GO

-- ==========================================================================================
-- Triggers
-- ==========================================================================================
-- dbo.trMoved: Table: source dbo.MoveA, target dbo.MoveB
-- The trigger is on another table on the two sides, and ALTER cannot move a trigger. To change it, drop the trigger and create it again by hand:
-- DROP TRIGGER [dbo].[trMoved];
-- GO
-- CREATE TRIGGER dbo.trMoved ON dbo.MoveB AFTER INSERT AS SET NOCOUNT ON;
-- GO

-- ==========================================================================================
-- Synonyms (base objects often name environment-specific databases: check them)
-- ==========================================================================================
-- Not run: dbo.synRemote is a synonym for an object in another database or on another server (BaseObject: source [otherdb_dev].[dbo].[Orders], target [otherdb_prod].[dbo].[Orders]). Check that name for this environment, then run by hand:
-- DROP SYNONYM [dbo].[synRemote];
-- CREATE SYNONYM [dbo].[synRemote] FOR [otherdb_prod].[dbo].[Orders];

-- ==========================================================================================
-- Database settings (not changed by this script)
-- ==========================================================================================
-- CompatibilityLevel: source 150, target 140

-- ==========================================================================================
-- Not compared (1 items): a value is not readable on one side, so nothing is scripted for these
-- ==========================================================================================
-- Stored procedure dbo.pSecret: Definition: not readable on either side

-- End of script: ends the NOEXEC that a failed database check at the top turned on.
SET NOEXEC OFF;
GO
